    await z.idle(o);
    await z.idle(o);
    // #PLAY 7
    z.play("7");
    // #CHANGE BLUE SOLID WHITE SOLID
    z.change("blue", "solid", "white", "solid");
    // #PLAY 7
    z.play("7");
    // #CHANGE WHITE SOLID BLUE SOLID
    z.change("white", "solid", "blue", "solid");
    // /I/I
    await z.idle(o);
    await z.idle(o);
    // #CHANGE BLUE SOLID WHITE SOLID
    z.change("blue", "solid", "white", "solid");
    // #PLAY 7
    z.play("7");
    // #CHANGE WHITE SOLID BLUE SOLID
    z.change("white", "solid", "blue", "solid");
    // #PLAY 7
    z.play("7");
    // /I/I/I/I
    await z.idle(o);
    await z.idle(o);
    await z.idle(o);
    await z.idle(o);
    // #PLAY 7777
    z.play("7777");
    // #CHANGE BLUE SOLID WHITE SOLID
    z.change("blue", "solid", "white", "solid");
    // #PLAY 9999
    z.play("9999");
    // /I
    await z.idle(o);
    // #CHANGE WHITE SOLID BLUE SOLID
